function sectionOf(ch){return MENU_SECTIONS.find(s=>ch>=s.from&&ch<=s.to)||{from:ch,to:ch,ru:'Русское издание',he:''}}
function initSections(){
  const sb=document.getElementById('sidebar');if(!sb||sb.dataset.sections)return;sb.dataset.sections='1';
  const btns=[...sb.querySelectorAll('.chapter-nav[data-chapter]')];
  const seifNav=document.getElementById('seifNav');
  const bottom=sb.querySelector('.side-bottom');
  const oldCaps=[...sb.querySelectorAll('.section-caption')];
  const oldLists=[...sb.querySelectorAll('.chapter-list')];
  const groups=MENU_SECTIONS.map(s=>({s,cap:null,body:document.createElement('div')}));
  btns.sort((x,y)=>Number(x.dataset.chapter)-Number(y.dataset.chapter)).forEach(b=>{const g=groups.find(g=>Number(b.dataset.chapter)>=g.s.from&&Number(b.dataset.chapter)<=g.s.to);if(g)g.body.appendChild(b)});
  groups.forEach(g=>{
    const body=g.body,s=g.s,filled=body.querySelectorAll('[data-chapter]').length>0;
    body.className='section-body chapter-list';body.hidden=true;
    const cap=document.createElement('div');cap.className='side-caption section-caption'+(filled?'':' empty');cap.title='הלכות '+s.he;
    const t=document.createElement('span');t.className='sec-title';t.textContent=s.ru;
    const r=document.createElement('span');r.className='sec-range';r.textContent=s.from===s.to?String(s.from):s.from+'–'+s.to;
    cap.append(t,r);
    if(filled){
      cap.setAttribute('role','button');cap.setAttribute('tabindex','0');cap.setAttribute('aria-expanded','false');
      const toggle=()=>{const open=body.hidden;body.hidden=!open;cap.setAttribute('aria-expanded',String(open))};
      cap.onclick=toggle;cap.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}};
    }else{cap.setAttribute('aria-disabled','true')}
    sb.append(cap,body);g.cap=cap;
  });
  oldCaps.forEach(c=>c.remove());
  if(seifNav)sb.append(seifNav);if(bottom)sb.append(bottom);
  oldLists.forEach(l=>{if(!l.querySelector('[data-chapter],#seifNav'))l.remove()});
}
function openSectionOf(ch){
  initSections();
  const b=document.querySelector(`.section-body [data-chapter="${ch}"]`);if(!b)return;
  const body=b.closest('.section-body');if(body.hidden){body.hidden=false;body.previousElementSibling.setAttribute('aria-expanded','true')}
}
initSections();
init();
